        vars["t"] = 0.0;
        vars["gamma"] = 5e-5;
        vars["pi"] = 3.14159265359;
        vars["mu_over_rj"] = 2.26e10;
        vars["P_SCm"] = 1.0;
        vars["E_react"] = 1e46;
