double WolframFieldUnityEngine_S116::computeDynamicContribution(double t) const
{
    if (!enableDynamicTerms)
        return 0.0;
    double sum = 0.0;
    for (const auto &term : dynamicTerms)
    {
        sum += term->compute(t);
    }
    return sum;
}

