// [Bulk comment]     }

// Volume computation for fluid
// [Bulk comment]     double compute_V() const
// [Bulk comment]     {
// [Bulk comment]         return (4.0 / 3.0) * M_PI * r * r * r;
// [Bulk comment]     }

// Main MUGE computation (includes ALL terms)
// [Bulk comment]     double compute_g_HUDF(double t) const
// [Bulk comment]     {
// [Bulk comment]         if (t < 0)
// [Bulk comment]         {
// [Bulk comment]             std::cerr << "Error: Time t must be non-negative." << std::endl;
// [Bulk comment]             return 0.0;
// [Bulk comment]         }

// [Bulk comment]         double Mt = M_t(t);
// [Bulk comment]         double It = I_t(t);
// [Bulk comment]         double ug1_t = (G * Mt) / (r * r);

// Term 1: Base + Hz + B + I corrections
// [Bulk comment]         double corr_H = 1 + Hz * t;
// [Bulk comment]         double corr_B = 1 - B / B_crit;
// [Bulk comment]         double corr_I = 1 + It;
// [Bulk comment]         double term1 = ug1_t * corr_H * corr_B * corr_I;

// Term 2: UQFF Ug with f_TRZ and I
// [Bulk comment]         double term2 = compute_Ug(Mt, It);

// Term 3: Lambda
// [Bulk comment]         double term3 = (Lambda * c_light * c_light) / 3.0;

// Term 4: Scaled EM with UA
// [Bulk comment]         double cross_vB = gas_v * B; // Magnitude, assuming perpendicular
// [Bulk comment]         double em_base = (q_charge * cross_vB) / proton_mass;
// [Bulk comment]         double corr_UA = 1 + (rho_vac_UA / rho_vac_SCm);
// [Bulk comment]         double term4 = (em_base * corr_UA) * scale_EM;

// Quantum uncertainty term
// [Bulk comment]         double sqrt_unc = sqrt(delta_x * delta_p);
// [Bulk comment]         double term_q = (hbar / sqrt_unc) * integral_psi * (2 * M_PI / t_Hubble);

// Fluid term (effective acceleration)
// [Bulk comment]         double V = compute_V();
// [Bulk comment]         double term_fluid = (rho_fluid * V * ug1_t) / Mt;

// Oscillatory terms (real parts)
// [Bulk comment]         double term_osc1 = 2 * A_osc * cos(k_osc * x_pos) * cos(omega_osc * t);
// [Bulk comment]         double arg = k_osc * x_pos - omega_osc * t;
// [Bulk comment]         double term_osc2 = (2 * M_PI / t_Hubble_gyr) * A_osc * cos(arg);
// [Bulk comment]         double term_osc = term_osc1 + term_osc2;

// DM and density perturbation term (converted to acceleration)
// [Bulk comment]         double M_dm = Mt * M_DM_factor;
// [Bulk comment]         double pert1 = delta_rho_over_rho;
// [Bulk comment]         double pert2 = 3 * G * Mt / (r * r * r);
// [Bulk comment]         double term_dm_force_like = (Mt + M_dm) * (pert1 + pert2);
// [Bulk comment]         double term_DM = term_dm_force_like / Mt;

// Merger feedback term (pressure / density for acceleration)
// [Bulk comment]         double wind_pressure = rho_wind * v_wind * v_wind;
// [Bulk comment]         double term_feedback = wind_pressure / rho_fluid;

// Total g_HUDF (all terms summed)
// [Bulk comment]         return term1 + term2 + term3 + term4 + term_q + term_fluid + term_osc + term_DM + term_feedback;
// [Bulk comment]     }

// Debug/Output method (for transparency in base program)
// [Bulk comment]     void printParameters(std::ostream &os = std::cout) const
// [Bulk comment]     {
// [Bulk comment]         os << std::fixed << std::setprecision(3);
