// [Bulk comment - extracted duplicates] compute_g_Westerlund2(double t) const
// [Bulk comment - extracted duplicates]     {
// [Bulk comment - extracted duplicates]         if (t < 0)
// [Bulk comment - extracted duplicates]         {
// [Bulk comment - extracted duplicates]             std::cerr << "Error: Time t must be non-negative." << std::endl;
// [Bulk comment - extracted duplicates]             return 0.0;
// [Bulk comment - extracted duplicates]         }

// [Bulk comment - extracted duplicates]         double Mt = M_t(t);
// [Bulk comment - extracted duplicates]         double ug1_t = (G * Mt) / (r * r);

// Term 1: Base + H0 + B corrections
// [Bulk comment - extracted duplicates]         double corr_H = 1 + H0 * t;
// [Bulk comment - extracted duplicates]         double corr_B = 1 - B / B_crit;
// [Bulk comment - extracted duplicates]         double term1 = ug1_t * corr_H * corr_B;

// Term 2: UQFF Ug with f_TRZ
// [Bulk comment - extracted duplicates]         double term2 = compute_Ug(Mt);

// Term 3: Lambda
// [Bulk comment - extracted duplicates]         double term3 = (Lambda * c_light * c_light) / 3.0;

// Term 4: Scaled EM with UA
// [Bulk comment - extracted duplicates]         double cross_vB = gas_v * B; // Magnitude, assuming perpendicular
// [Bulk comment - extracted duplicates]         double em_base = (q_charge * cross_vB) / proton_mass;
// [Bulk comment - extracted duplicates]         double corr_UA = 1 + (rho_vac_UA / rho_vac_SCm);
// [Bulk comment - extracted duplicates]         double term4 = (em_base * corr_UA) * scale_EM;

// Quantum uncertainty term
// [Bulk comment - extracted duplicates]         double sqrt_unc = sqrt(delta_x * delta_p);
// [Bulk comment - extracted duplicates]         double term_q = (hbar / sqrt_unc) * integral_psi * (2 * M_PI / t_Hubble);

// Fluid term (effective acceleration)
// [Bulk comment - extracted duplicates]         double V = compute_V();
// [Bulk comment - extracted duplicates]         double term_fluid = (rho_fluid * V * ug1_t) / Mt;

// Oscillatory terms (real parts)
// [Bulk comment - extracted duplicates]         double term_osc1 = 2 * A_osc * cos(k_osc * x_pos) * cos(omega_osc * t);
// [Bulk comment - extracted duplicates]         double arg = k_osc * x_pos - omega_osc * t;
// [Bulk comment - extracted duplicates]         double term_osc2 = (2 * M_PI / t_Hubble_gyr) * A_osc * cos(arg);
// [Bulk comment - extracted duplicates]         double term_osc = term_osc1 + term_osc2;

// DM and density perturbation term (converted to acceleration)
// [Bulk comment - extracted duplicates]         double M_dm = Mt * M_DM_factor;
// [Bulk comment - extracted duplicates]         double pert1 = delta_rho_over_rho;
// [Bulk comment - extracted duplicates]         double pert2 = 3 * G * Mt / (r * r * r);
// [Bulk comment - extracted duplicates]         double term_dm_force_like = (Mt + M_dm) * (pert1 + pert2);
// [Bulk comment - extracted duplicates]         double term_DM = term_dm_force_like / Mt;

// Stellar wind feedback term (pressure / density for acceleration)
// [Bulk comment - extracted duplicates]         double wind_pressure = rho_wind * v_wind * v_wind;
// [Bulk comment - extracted duplicates]         double term_wind = wind_pressure / rho_fluid;

// Total g_Westerlund2 (all terms summed)
// [Bulk comment - extracted duplicates]         return term1 + term2 + term3 + term4 + term_q + term_fluid + term_osc + term_DM + term_wind;
// [Bulk comment - extracted duplicates]     }

